(()=>{'use strict';
const NS='http://www.w3.org/2000/svg',MAX_MARKS=1400,FORMATS={mini8:{totalBits:8,expBits:3,fracBits:4,bias:3},half16:{totalBits:16,expBits:5,fracBits:10,bias:15}};
const $=id=>document.getElementById(id),els={svg:$('numberLine'),tip:$('tooltip'),input:$('decimalInput'),slider:$('valueSlider'),gap:$('gapToggle')};
let formatKey='mini8',F,canonical,values,MIN,MAX,selected,view,dragging=false,lastX=0;
function decode(raw){const sign=raw>>(F.totalBits-1)&1,exp=raw>>F.fracBits&((1<<F.expBits)-1),frac=raw&((1<<F.fracBits)-1),bits=raw.toString(2).padStart(F.totalBits,'0'),maxExp=(1<<F.expBits)-1,denom=2**F.fracBits;let kind,value,actualExp,significand;if(exp===maxExp){kind=frac?'nan':'infinity';value=frac?NaN:(sign?-Infinity:Infinity)}else if(!exp){actualExp=1-F.bias;significand=frac/denom;value=(sign?-1:1)*significand*2**actualExp;kind=frac?'subnormal':'zero'}else{actualExp=exp-F.bias;significand=1+frac/denom;value=(sign?-1:1)*significand*2**actualExp;kind='normal'}return{raw,sign,exp,frac,bits,value,kind,actualExp,significand}}
function buildFormat(key,keep=5.3){formatKey=key;F=FORMATS[key];const byValue=new Map();for(let i=0;i<2**F.totalBits;i++){const n=decode(i);if(Number.isFinite(n.value)&&!byValue.has(n.value))byValue.set(n.value,n)}values=[...byValue.keys()].sort((a,b)=>a-b);canonical=values.map(v=>byValue.get(v));MIN=values[0];MAX=values.at(-1);const input=Math.max(MIN,Math.min(MAX,Number(keep)||0));els.input.value=input;els.slider.min=MIN;els.slider.max=MAX;els.slider.step=key==='half16'?'.01':'.001';els.slider.value=input;selected=towardsZero(input);resetView();updateFormatUI();updateDetails();renderAxis()}
function lowerBound(x){let l=0,r=values.length;while(l<r){const m=l+r>>1;if(values[m]<x)l=m+1;else r=m}return l}function upperBound(x){let l=0,r=values.length;while(l<r){const m=l+r>>1;if(values[m]<=x)l=m+1;else r=m}return l}
function towardsZero(x){const i=x<0?lowerBound(x):upperBound(x)-1;return canonical[Math.max(0,Math.min(canonical.length-1,i))]}function neighbors(x){return{lo:values[Math.max(0,upperBound(x)-1)],hi:values[Math.min(values.length-1,lowerBound(x))]}}
function fmt(n,d=8){if(Object.is(n,-0))return'−0';if(!Number.isFinite(n))return String(n);const a=Math.abs(n);if(a&&(a<1e-6||a>=1e6))return n.toExponential(6).replace('.',',');return new Intl.NumberFormat('de-DE',{maximumFractionDigits:d,useGrouping:false}).format(n)}
function svgEl(tag,attrs={}){const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);return e}function niceStep(range){const rough=range/8,p=10**Math.floor(Math.log10(rough)),m=rough/p;return(m<2?2:m<5?5:10)*p}function xPos(v,w){return(v-view.min)/(view.max-view.min)*w}
function renderAxis(){const w=els.svg.clientWidth||1e3,h=340,y=165;els.svg.setAttribute('viewBox',`0 0 ${w} ${h}`);els.svg.replaceChildren();const start=lowerBound(view.min),end=upperBound(view.max),count=Math.max(0,end-start),stride=Math.max(1,Math.ceil(count/MAX_MARKS));if(els.gap.checked)for(let i=start;i<end-1;i+=stride){const a=values[i],b=values[Math.min(end-1,i+stride)],alpha=Math.min(.28,.04+Math.log2(1+Math.abs(b-a))/30);els.svg.append(svgEl('rect',{x:xPos(a,w),y:110,width:Math.max(0,xPos(b,w)-xPos(a,w)),height:110,fill:`rgba(240,100,43,${alpha})`}))}els.svg.append(svgEl('line',{x1:0,y1:y,x2:w,y2:y,stroke:'#64716b'}));const step=niceStep(view.max-view.min),tickStart=Math.ceil(view.min/step)*step;for(let v=tickStart;v<=view.max+step/10;v+=step){const x=xPos(v,w);els.svg.append(svgEl('line',{x1:x,y1:y-9,x2:x,y2:y+9,stroke:'#7e8984'}));const t=svgEl('text',{x,y:y+30,fill:'#99a49f','font-size':11,'text-anchor':'middle'});t.textContent=fmt(Math.abs(v)<1e-15?0:v,4);els.svg.append(t)}const shown=[];for(let i=start;i<end;i+=stride)shown.push(canonical[i]);if(selected.value>=view.min&&selected.value<=view.max&&!shown.includes(selected))shown.push(selected);const pxPer=w/(view.max-view.min);for(const n of shown){const x=xPos(n.value,w),major=!n.frac||n.kind==='subnormal',line=svgEl('line',{x1:x,x2:x,y1:y-(major?35:20),y2:y+(major?35:20),stroke:n.raw===selected.raw?'#e9c94b':n.kind==='subnormal'?'#8b65db':'#c5cec9','stroke-width':n.raw===selected.raw?4:Math.max(1,Math.min(2,pxPer/9)),opacity:n.raw===selected.raw?1:.78,tabindex:0});line.style.cursor='pointer';line.onpointerenter=e=>showTip(e,n);line.onpointermove=e=>showTip(e,n);line.onpointerleave=()=>els.tip.hidden=true;line.onclick=e=>{e.stopPropagation();selected=n;updateDetails();renderAxis()};els.svg.append(line)}$('axisDensity').textContent=stride>1?`${fmt(count,0)} Werte · jeder ${stride}. Strich gezeigt · hineinzoomen für Details`:`${fmt(count,0)} darstellbare Werte im Ausschnitt`;drawMarker(+els.input.value,w,y,'#f0642b','Eingabe',0);drawMarker(selected.value,w,y,'#e9c94b','Abgeschnitten',1)}
function drawMarker(v,w,y,color,label,row){if(!Number.isFinite(v)||v<view.min||v>view.max)return;const x=xPos(v,w),g=svgEl('g');g.append(svgEl('line',{x1:x,x2:x,y1:64+row*25,y2:y-42,stroke:color,'stroke-width':2,'stroke-dasharray':'4 4'}));g.append(svgEl('circle',{cx:x,cy:y-42,r:6,fill:color,stroke:'#111916','stroke-width':3}));const t=svgEl('text',{x:x+7,y:59+row*25,fill:color,'font-size':11,'font-weight':700});t.textContent=`${label}: ${fmt(v)}`;g.append(t);els.svg.append(g)}
function showTip(e,n){const r=els.svg.getBoundingClientRect(),split=1+F.expBits;els.tip.hidden=false;els.tip.innerHTML=`<b>${fmt(n.value)}</b><br><code>${n.bits[0]} | ${n.bits.slice(1,split)} | ${n.bits.slice(split)}</code> · ${{normal:'normal',subnormal:'subnormal',zero:'Null'}[n.kind]}`;els.tip.style.left=Math.min(r.width-230,e.clientX-r.left+12)+'px';els.tip.style.top=Math.max(8,e.clientY-r.top-55)+'px'}
function update(){const x=+els.input.value;if(!Number.isFinite(x))return;selected=towardsZero(x);updateDetails();renderAxis()}
function updateDetails(){const x=+els.input.value,n=selected,{lo,hi}=neighbors(x),abs=Math.abs(x-n.value),rel=x===0?(abs?Infinity:0):abs/Math.abs(x)*100,split=1+F.expBits,fracBits=n.bits.slice(split),expBits=n.bits.slice(1,split);$('wantedValue').textContent=fmt(x);$('roundedValue').textContent=fmt(n.value);$('absoluteError').textContent=fmt(abs);$('relativeError').textContent=Number.isFinite(rel)?fmt(rel,5)+' %':'∞';$('lowerNeighbor').textContent=fmt(lo);$('upperNeighbor').textContent=fmt(hi);const span=hi-lo||1;$('journeyTarget').style.left=Math.max(0,Math.min(100,(x-lo)/span*100))+'%';$('journeyRounded').style.left=Math.max(0,Math.min(100,(n.value-lo)/span*100))+'%';$('bitDisplay').replaceChildren(...[...n.bits].map((b,i)=>{const s=document.createElement('span');s.className='bit '+(i===0?'sign':i<split?'exp':'mant');s.textContent=b;s.title=i===0?'Vorzeichen':i<split?'Exponent':'Mantisse';return s}));let html;if(n.kind==='zero')html=`<b>${n.sign?'Negative':'Positive'} Null</b><br>Exponentenfeld: <code>${expBits}₂ = 0</code><br><code>(−1)<sup>${n.sign}</sup> × 0 = ${fmt(n.value)}</code>`;else if(n.kind==='subnormal')html=`<b>Subnormalzahl</b> — keine implizite 1<br>Vorzeichen: <code>(−1)<sup>${n.sign}</sup></code> · Exponentenfeld: <code>${expBits}₂ = 0</code><br>Effektiver Exponent: <code>1 − ${F.bias} = ${n.actualExp}</code><br>Signifikand: <code>0.${fracBits}₂ = ${fmt(n.significand,12)}</code><br><code>(−1)<sup>${n.sign}</sup> × ${fmt(n.significand,12)} × 2<sup>${n.actualExp}</sup> = <b>${fmt(n.value,12)}</b></code>`;else html=`<b>Normalisierte Zahl</b> — implizite führende 1<br>Vorzeichen: <code>(−1)<sup>${n.sign}</sup></code> · Exponentenfeld: <code>${expBits}₂ = ${n.exp}</code><br>Effektiver Exponent: <code>${n.exp} − ${F.bias} = ${n.actualExp}</code><br>Signifikand: <code>1.${fracBits}₂ = ${fmt(n.significand,12)}</code><br><code>(−1)<sup>${n.sign}</sup> × ${fmt(n.significand,12)} × 2<sup>${n.actualExp}</sup> = <b>${fmt(n.value,12)}</b></code>`;$('formula').innerHTML=html}
function updateFormatUI(){document.querySelectorAll('[data-format]').forEach(b=>{const on=b.dataset.format===formatKey;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on)});document.querySelector('.format-card').dataset.wide=F.totalBits===16;$('formatSign').textContent=1;$('formatExp').textContent=F.expBits;$('formatMant').textContent=F.fracBits;$('formatSummary').textContent=`${F.totalBits} Bit · Bias ${F.bias} · Vorzeichen / Exponent / Mantisse`;$('footerFormat').textContent=`1 Vorzeichenbit · ${F.expBits} Exponentenbits · ${F.fracBits} Mantissenbits · Bias ${F.bias}`;$('bitDisplay').setAttribute('aria-label',`${F.totalBits}-Bit-Darstellung`)}
function setValue(v){v=Math.max(MIN,Math.min(MAX,+v));els.input.value=v;els.slider.value=v;update()}function resetView(){const p=(MAX-MIN)*.025;view={min:MIN-p,max:MAX+p}}
els.input.oninput=()=>{const v=+els.input.value;if(Number.isFinite(v))els.slider.value=Math.max(MIN,Math.min(MAX,v));update()};els.slider.oninput=()=>setValue(els.slider.value);els.gap.onchange=renderAxis;document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>buildFormat(b.dataset.format,els.input.value));
els.svg.addEventListener('wheel',e=>{e.preventDefault();const r=els.svg.getBoundingClientRect(),anchor=view.min+(e.clientX-r.left)/r.width*(view.max-view.min),factor=e.deltaY>0?1.25:.8,full=(MAX-MIN)*1.05,minRange=formatKey==='half16'?1e-7:1e-4,newRange=Math.min(full,Math.max(minRange,(view.max-view.min)*factor)),ratio=(anchor-view.min)/(view.max-view.min);view.min=anchor-newRange*ratio;view.max=view.min+newRange;renderAxis()},{passive:false});els.svg.onpointerdown=e=>{dragging=true;lastX=e.clientX;els.svg.setPointerCapture(e.pointerId);els.svg.classList.add('dragging')};els.svg.onpointermove=e=>{if(!dragging)return;const d=-(e.clientX-lastX)/els.svg.clientWidth*(view.max-view.min);view.min+=d;view.max+=d;lastX=e.clientX;renderAxis()};els.svg.onpointerup=()=>{dragging=false;els.svg.classList.remove('dragging')};
function zoom(f){const c=(view.min+view.max)/2,r=(view.max-view.min)*f/2;view={min:c-r,max:c+r};renderAxis()}$('zoomIn').onclick=()=>zoom(.6);$('zoomOut').onclick=()=>zoom(1.6);$('resetView').onclick=()=>{resetView();renderAxis()};document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{setValue(b.dataset.example);els.svg.scrollIntoView({behavior:'smooth',block:'center'})});window.onresize=renderAxis;buildFormat('mini8');
})();
